/// In the data directory of a node that has left its cluster.
pub const DETACHED_MARKER: &str = "pgcluster.detached";

pub struct AgentServiceImpl {
    config: Arc<AgentConfig>,
    heartbeat: Arc<HeartbeatTracker>,
    pg: Arc<LocalPostgres>,
    pg_ctl: Arc<PgCtl>,
    seeding: Mutex<()>,
    walg: WalG,
}

impl AgentServiceImpl {
    pub fn new(
        config: Arc<AgentConfig>,
        heartbeat: Arc<HeartbeatTracker>,
        pg: Arc<LocalPostgres>,
        pg_ctl: Arc<PgCtl>,
    ) -> Self {
        let walg = WalG::new(&config);
        Self {
            config,
            heartbeat,
            pg,
            pg_ctl,
            seeding: Mutex::new(()),
            walg,
        }
    }

    async fn has_data(&self) -> bool {
        crate::seed::has_data(Path::new(&self.config.data_dir))
            .await
            .unwrap_or(false)
    }

    /// Stop Postgres. When this agent owns the process it starts it again, so a
    /// demoted primary comes back as a standby. Otherwise its owner restarts it.
    async fn stop_and_restart(&self) -> anyhow::Result<()> {
        self.pg_ctl.stop_fast().await?;
        if self.config.manage_postgres {
            self.pg_ctl.start().await?;
        }
        Ok(())
    }

    /// Seed and rewind stop Postgres, so they need this agent to own it, and
    /// only one runs at a time.
    fn begin_lifecycle_change(&self) -> anyhow::Result<MutexGuard<'_, ()>> {
        if !self.config.manage_postgres {
            anyhow::bail!("this agent does not manage Postgres (manage_postgres = false)");
        }
        self.seeding
            .try_lock()
            .map_err(|_| anyhow::anyhow!("a seed or rewind is already running"))
    }
}

/// Serve the agent gRPC service until the server fails. `tls` of `None` means
/// plaintext, for development.
pub async fn serve(
    svc: AgentServiceImpl,
    addr: std::net::SocketAddr,
    tls: Option<ServerTlsConfig>,
) -> anyhow::Result<()> {
    let mut builder = Server::builder();
    if let Some(tls) = tls {
        builder = builder.tls_config(tls)?;
    }
    builder
        .add_service(AgentServiceServer::new(svc))
        .serve(addr)
        .await?;
    Ok(())
}

#[tonic::async_trait]
impl AgentService for AgentServiceImpl {
    /// Promote this standby to primary via `SELECT pg_promote()`.
    ///
    /// Using the SQL function is more reliable than writing `promote.signal`
    /// because it works over an existing authenticated connection and does not
    /// require the agent to have write access to PGDATA.
    async fn promote(
        &self,
        _request: Request<PromoteRequest>,
    ) -> Result<Response<PromoteResponse>, Status> {
        // Refuse promotion when the heartbeat watchdog has entered safe mode.
        // This prevents a stale pgcluster leader from causing split-brain.
        if self.heartbeat.is_safe_mode() {
            tracing::warn!("promote RPC rejected: agent is in safe mode (heartbeat lost)");
            return Ok(Response::new(PromoteResponse {
                success: false,
                error:
                    "safe mode: pgcluster heartbeat lost — promote rejected to prevent split-brain"
                        .into(),
                promoted_at_lsn: 0,
                new_timeline: 0,
            }));
        }
        // pg_promote(wait, wait_seconds) — wait up to 30 s for promotion to complete.
        match sqlx::query("SELECT pg_promote(true, 30)")
            .execute(self.pg.pool())
            .await
        {
            Ok(_) => Ok(Response::new(PromoteResponse {
                success: true,
                error: String::new(),
                promoted_at_lsn: 0,
                new_timeline: 0,
            })),
            Err(e) => Ok(Response::new(PromoteResponse {
                success: false,
                error: e.to_string(),
                promoted_at_lsn: 0,
                new_timeline: 0,
            })),
        }
    }

    /// Demote this node to a standby by writing `standby.signal`,
    /// updating `postgresql.auto.conf`, and removing `promote.signal`.
    ///
    /// If `new_primary_conninfo` contains `password=<value>`, the password is
    /// extracted, written to `PGDATA/.pgpass` (mode 0600), and replaced with
    /// `passfile=<path>` in the stored conninfo so that credentials are never
    /// stored in plaintext inside the config file.
    async fn demote(
        &self,
        request: Request<DemoteRequest>,
    ) -> Result<Response<DemoteResponse>, Status> {
        let req = request.into_inner();
        let data_dir = Path::new(&self.config.data_dir);

        let result = configure_standby(
            data_dir,
            &req.new_primary_conninfo,
            &req.slot_name,
            &req.application_name,
        )
        .await;

        // Remove promote.signal if present; ignore errors.
        let _ = tokio::fs::remove_file(data_dir.join("promote.signal")).await;

        // primary_conninfo applies on reload, so a running standby switches to
        // the new primary now. A primary ignores it until it restarts.
        if result.is_ok() {
            if let Err(e) = self.pg_ctl.reload().await {
                tracing::warn!(err = %e, "reload after demote failed");
            }
        }

        Ok(Response::new(DemoteResponse {
            success: result.is_ok(),
            error: result.err().map(|e| format!("{e:#}")).unwrap_or_default(),
        }))
    }

    /// Seed this node from the primary.
    async fn seed(&self, request: Request<SeedRequest>) -> Result<Response<SeedResponse>, Status> {
        let data_dir = Path::new(&self.config.data_dir);
        let req = request.into_inner();
        let result = match self.begin_lifecycle_change() {
            Ok(_guard) => crate::seed::seed(&self.pg_ctl, data_dir, &req).await,
            Err(e) => Err(e),
        };
        Ok(Response::new(SeedResponse {
            success: result.is_ok(),
            error: result.err().map(|e| format!("{e:#}")).unwrap_or_default(),
        }))
    }

    /// Rewind this node to the primary.
    async fn rewind(
        &self,
        request: Request<SeedRequest>,
    ) -> Result<Response<SeedResponse>, Status> {
        let data_dir = Path::new(&self.config.data_dir);
        let req = request.into_inner();
        let result = match self.begin_lifecycle_change() {
            Ok(_guard) => crate::seed::rewind(&self.pg_ctl, data_dir, &req).await,
            Err(e) => Err(e),
        };
        Ok(Response::new(SeedResponse {
            success: result.is_ok(),
            error: result.err().map(|e| format!("{e:#}")).unwrap_or_default(),
        }))
    }

    async fn configure_backups(
        &self,
        request: Request<ConfigureBackupsRequest>,
    ) -> Result<Response<SeedResponse>, Status> {
        let req = request.into_inner();
        let result = self
            .walg
            .configure(&self.pg, &req.settings, &req.version)
            .await;
        Ok(Response::new(SeedResponse {
            success: result.is_ok(),
            error: result.err().map(|e| format!("{e:#}")).unwrap_or_default(),
        }))
    }

    async fn backup_push(
        &self,
        _request: Request<BackupPushRequest>,
    ) -> Result<Response<BackupPushResponse>, Status> {
        let data_dir = Path::new(&self.config.data_dir);
        Ok(Response::new(match self.walg.backup_push(data_dir).await {
            Ok((backup_name, size_bytes)) => BackupPushResponse {
                success: true,
                error: String::new(),
                backup_name,
                size_bytes,
            },
            Err(e) => BackupPushResponse {
                success: false,
                error: format!("{e:#}"),
                ..Default::default()
            },
        }))
    }

    async fn backup_delete(
        &self,
        request: Request<BackupDeleteRequest>,
    ) -> Result<Response<BackupDeleteResponse>, Status> {
        let req = request.into_inner();
        Ok(Response::new(
            match self.walg.delete(req.retain_full, &req.target).await {
                Ok(remaining) => BackupDeleteResponse {
                    success: true,
                    error: String::new(),
                    remaining,
                },
                Err(e) => BackupDeleteResponse {
                    success: false,
                    error: format!("{e:#}"),
                    remaining: vec![],
                },
            },
        ))
    }

    async fn backup_verify(
        &self,
        _request: Request<BackupVerifyRequest>,
    ) -> Result<Response<BackupVerifyResponse>, Status> {
        Ok(Response::new(match self.walg.verify().await {
            Ok(report) => BackupVerifyResponse {
                success: true,
                error: String::new(),
                report,
            },
            Err(e) => BackupVerifyResponse {
                success: false,
                error: format!("{e:#}"),
                report: String::new(),
            },
        }))
    }

    async fn restore(
        &self,
        request: Request<RestoreRequest>,
    ) -> Result<Response<SeedResponse>, Status> {
        let data_dir = Path::new(&self.config.data_dir);
        let req = request.into_inner();
        let result = match self.begin_lifecycle_change() {
            Ok(_guard) => self.walg.restore(&self.pg_ctl, data_dir, &req).await,
            Err(e) => Err(e),
        };
        Ok(Response::new(SeedResponse {
            success: result.is_ok(),
            error: result.err().map(|e| format!("{e:#}")).unwrap_or_default(),
        }))
    }

    /// Leave the cluster as an independent primary. The marker keeps this node
    /// from fencing itself after a restart, when no pgcluster will heartbeat it.
    async fn detach(
        &self,
        _request: Request<DetachRequest>,
    ) -> Result<Response<SeedResponse>, Status> {
        let data_dir = Path::new(&self.config.data_dir);
        self.heartbeat.detach();
        let result = async {
            tokio::fs::write(data_dir.join(DETACHED_MARKER), b"")
                .await
                .map_err(anyhow::Error::from)?;
            self.pg.detach().await
        }
        .await;
        Ok(Response::new(SeedResponse {
            success: result.is_ok(),
            error: result.err().map(|e| format!("{e:#}")).unwrap_or_default(),
        }))
    }

    async fn set_proxy_auth(
        &self,
        request: Request<SetProxyAuthRequest>,
    ) -> Result<Response<SeedResponse>, Status> {
        let req = request.into_inner();
        let result = self
            .pg
            .set_proxy_auth(&req.user, &req.password, &req.version)
            .await;
        Ok(Response::new(SeedResponse {
            success: result.is_ok(),
            error: result.err().map(|e| format!("{e:#}")).unwrap_or_default(),
        }))
    }

    /// Return current node status: role, LSNs, timeline, version, connection
    /// count, and replication info.
    async fn get_status(
        &self,
        _request: Request<StatusRequest>,
    ) -> Result<Response<StatusResponse>, Status> {
        let safe_mode = self.heartbeat.is_safe_mode();

        // If Postgres is not reachable, return a minimal status rather than an
        // RPC error so callers can still observe the node state.
        if !self.pg.is_running().await {
            return Ok(Response::new(StatusResponse {
                is_in_recovery: false,
                received_lsn: 0,
                replayed_lsn: 0,
                sent_lsn: 0,
                timeline: 0,
                postgres_version: String::new(),
                active_connections: 0,
                postgres_running: false,
                replicas: vec![],
                replication_conninfo: String::new(),
                parameters: Default::default(),
                lost_slots: vec![],
                has_data: self.has_data().await,
                backup_config_version: self.walg.config_version().await,
                proxy_auth_version: String::new(),
            }));
        }

        // Gather status; on any query error fall back to postgres_running=false.
        let is_recovery = match self.pg.is_in_recovery().await {
            Ok(v) => v,
            Err(e) => {
                tracing::warn!("is_in_recovery query failed: {e}");
                return Ok(Response::new(StatusResponse {
                    is_in_recovery: false,
                    received_lsn: 0,
                    replayed_lsn: 0,
                    sent_lsn: 0,
                    timeline: 0,
                    postgres_version: String::new(),
                    active_connections: 0,
                    postgres_running: false,
                    replicas: vec![],
                    replication_conninfo: String::new(),
                    parameters: Default::default(),
                    lost_slots: vec![],
                    has_data: self.has_data().await,
                    backup_config_version: self.walg.config_version().await,
                    proxy_auth_version: String::new(),
                }));
            }
        };

        let (received_lsn, replayed_lsn, sent_lsn) = if is_recovery {
            let recv = self.pg.get_receive_lsn().await.unwrap_or(0);
            let repl = self.pg.get_replay_lsn().await.unwrap_or(0);
            (recv, repl, 0u64)
        } else {
            let cur = self.pg.get_current_lsn().await.unwrap_or(0);
            (0u64, 0u64, cur)
        };

        let timeline = self.pg.get_timeline().await.unwrap_or(0);
        let version = self.pg.get_postgres_version().await.unwrap_or_default();
        let conns = self.pg.get_active_connections().await.unwrap_or(0);

        let replicas = if is_recovery {
            vec![]
        } else {
            self.pg.get_stat_replication().await.unwrap_or_default()
        };

        let replication_conninfo = if is_recovery {
            self.pg
                .get_wal_receiver_conninfo()
                .await
                .unwrap_or_default()
        } else {
            String::new()
        };

        let parameters = self.pg.get_parameters().await.unwrap_or_default();
        let lost_slots = if is_recovery {
            vec![]
        } else {
            self.pg.get_lost_slots().await.unwrap_or_default()
        };

        let _ = safe_mode; // exposed indirectly through heartbeat; not in StatusResponse proto

        Ok(Response::new(StatusResponse {
            is_in_recovery: is_recovery,
            received_lsn,
            replayed_lsn,
            sent_lsn,
            timeline,
            postgres_version: version,
            active_connections: conns,
            postgres_running: true,
            replicas,
            replication_conninfo,
            parameters,
            lost_slots,
            has_data: true,
            backup_config_version: self.walg.config_version().await,
            proxy_auth_version: self.pg.get_proxy_auth_version().await.unwrap_or_default(),
        }))
    }

    /// Apply settings pgcluster manages. Never touches the rest of the config.
    async fn set_parameters(
        &self,
        request: Request<SetParametersRequest>,
    ) -> Result<Response<SetParametersResponse>, Status> {
        let parameters = request.into_inner().parameters;
        let result = self.pg.set_parameters(&parameters).await;
        Ok(Response::new(SetParametersResponse {
            success: result.is_ok(),
            error: result.err().map(|e| format!("{e:#}")).unwrap_or_default(),
        }))
    }

    /// Record a heartbeat from the pgcluster leader.
    async fn heartbeat(
        &self,
        request: Request<HeartbeatRequest>,
    ) -> Result<Response<HeartbeatResponse>, Status> {
        let seq = request.into_inner().seq;
        self.heartbeat.touch();
        Ok(Response::new(HeartbeatResponse {
            in_safe_mode: self.heartbeat.is_safe_mode(),
            seq,
        }))
    }

    /// Stop the local Postgres instance using `pg_ctl stop -m fast`.
    async fn stop_postgres(
        &self,
        _request: Request<StopRequest>,
    ) -> Result<Response<StopResponse>, Status> {
        let result = self.stop_and_restart().await;
        match result {
            Ok(()) => Ok(Response::new(StopResponse {
                success: true,
                error: String::new(),
            })),
            Err(e) => Ok(Response::new(StopResponse {
                success: false,
                error: e.to_string(),
            })),
        }
    }

    /// Reload the Postgres configuration using `pg_ctl reload` (SIGHUP).
    async fn reload_config(
        &self,
        _request: Request<ReloadRequest>,
    ) -> Result<Response<ReloadResponse>, Status> {
        match self.pg_ctl.reload().await {
            Ok(()) => Ok(Response::new(ReloadResponse {
                success: true,
                error: String::new(),
            })),
            Err(e) => Ok(Response::new(ReloadResponse {
                success: false,
                error: e.to_string(),
            })),
        }
    }
}
